package org.example.repository;

import org.example.domain.Entity;
import org.example.validation.Validator;

import java.util.Collection;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Optional;
import java.util.function.Function;

/**
 * Repository that keeps the entities in memory, in a map id -&gt; entity.
 * LinkedHashMap keeps the insertion order (the lines in the files keep their order).
 * <p>
 * Lab 5: the id can be generated by the repository (the storage), not by the service.
 * The generator is a function that receives the ids already used and returns a new one;
 * without a generator, every saved entity must already have an id.
 *
 * @param <ID> the type of the entity id
 * @param <E> the type of the entities
 */
public class InMemoryRepository<ID, E extends Entity<ID>> implements Repository<ID, E> {
    /** the entities, by id; subclasses use it to restore the state when persisting fails */
    protected final Map<ID, E> entities = new LinkedHashMap<>();
    private final Validator<E> validator;
    private final Function<Collection<ID>, ID> idGenerator;

    /**
     * Repository whose entities always come with their id (e.g. friendships).
     *
     * @param validator used on every save and update
     */
    public InMemoryRepository(Validator<E> validator) {
        this(validator, null);
    }

    /**
     * Repository that generates the id of the entities saved without one.
     *
     * @param validator used on every save and update
     * @param idGenerator receives the ids already used and returns a new, unused id;
     *        null if the repository does not generate ids
     */
    public InMemoryRepository(Validator<E> validator, Function<Collection<ID>, ID> idGenerator) {
        this.validator = validator;
        this.idGenerator = idGenerator;
    }

    /**
     * {@inheritDoc}
     */
    @Override
    public Optional<E> findOne(ID id) {
        if (id == null) throw new IllegalArgumentException("Id-ul nu poate fi null!");
        return Optional.ofNullable(entities.get(id));
    }

    /**
     * {@inheritDoc}
     */
    @Override
    public Iterable<E> findAll() {
        return entities.values();
    }

    /**
     * {@inheritDoc}
     * The entity is validated before its id is generated.
     */
    @Override
    public Optional<E> save(E entity) {
        if (entity == null) throw new IllegalArgumentException("Entitatea nu poate fi null!");
        validator.validate(entity);
        if (entity.getId() == null) {
            if (idGenerator == null) throw new IllegalArgumentException("Id-ul nu poate fi null!");
            entity.setId(idGenerator.apply(entities.keySet()));
        }
        if (entities.containsKey(entity.getId())) return Optional.of(entity);
        entities.put(entity.getId(), entity);
        return Optional.empty();
    }

    /**
     * {@inheritDoc}
     */
    @Override
    public Optional<E> delete(ID id) {
        if (id == null) throw new IllegalArgumentException("Id-ul nu poate fi null!");
        return Optional.ofNullable(entities.remove(id));
    }

    /**
     * {@inheritDoc}
     */
    @Override
    public Optional<E> update(E entity) {
        if (entity == null) throw new IllegalArgumentException("Entitatea nu poate fi null!");
        if (entity.getId() == null) throw new IllegalArgumentException("Id-ul nu poate fi null!");
        validator.validate(entity);
        if (!entities.containsKey(entity.getId())) return Optional.of(entity);
        entities.put(entity.getId(), entity);
        return Optional.empty();
    }
}
